ol {
  counter-reset: my-counter;
  list-style: none;
}
li::before {
  counter-increment: my-counter;
  content: "Section " counter(my-counter) ": ";
}

@counter-style thumbs {
  system: cyclic;
  symbols: '👍' '👎';
  suffix: ' ';
}
ul {
  list-style: thumbs;
}

@counter-style letters {
  system: fixed;
  symbols: 'A' 'B';
  fallback: decimal;
}
ol {
  list-style: letters;
}

dl {
  display: grid;
  grid-template-columns: max-content 1fr;
}
dl > div {
  display: grid;
  grid-template-columns: subgrid;
  grid-column: 1 / -1;
}

